func TestDifferentContentConflictsAndIsNotStored(t *testing.T) {
	_, h := newTestRouter(t)
	postPlacement(t, h, validBody)
	different := `{
	  "namespace": "team-a", "name": "job-1", "queue": "default", "priority": 11,
	  "resources": {"cpu": 500, "memory": 256},
	  "selector": {"zone": "cn"}, "nodes": []
